// 인라인 버튼 콜백인지, 수정 지시 텍스트인지 판별한다.
// callback_data 는 텔레그램 규격상 64바이트 제한이라 'approve:INQ-...' 형태로만 실었다.

const j = $input.first().json;

let route = 'ignore';
let inquiry_id = '';
let instruction = '';
let callback_id = '';
let chat_id = '';

if (j.callback_query) {
  callback_id = j.callback_query.id || '';
  chat_id = (j.callback_query.message && j.callback_query.message.chat && j.callback_query.message.chat.id) || '';
  const data = String(j.callback_query.data || '');

  if (data.startsWith('approve:')) {
    route = 'approve';
    inquiry_id = data.slice('approve:'.length);
  } else if (data.startsWith('revise:')) {
    route = 'revise';
    inquiry_id = data.slice('revise:'.length);
  }
} else if (j.message && j.message.text) {
  const t = String(j.message.text).trim();
  chat_id = (j.message.chat && j.message.chat.id) || '';

  // 슬래시 명령이나 빈 문자열은 무시
  if (t && !t.startsWith('/')) {
    route = 'instruct';
    instruction = t;
  }
}

return [{ json: { route, inquiry_id, instruction, callback_id, chat_id } }];

// inquiry_id 로 대상 행을 찾는다. 행 번호로 찾지 않는 이유는
// 동시에 여러 건이 제출되면 행 번호가 어긋나기 때문이다.

const target = $('라우팅 판별').first().json.inquiry_id;
const rows = $input.all();

const hit = rows.find(r => String(r.json.inquiry_id || '').trim() === target);

if (!hit) {
  throw new Error(`문의를 찾을 수 없습니다: ${target}`);
}
if (!hit.json.draft_id) {
  throw new Error(`draft_id 가 비어 있습니다: ${target}`);
}
if (String(hit.json.status).trim() === '발송완료') {
  throw new Error(`이미 발송된 건입니다: ${target}`);   // 버튼 중복 클릭 방어
}

return [{ json: hit.json }];

// 담당자가 보낸 텍스트가 어떤 문의에 대한 수정 지시인지 알아내야 한다.
// 텔레그램 일반 메시지에는 문의 정보가 없으므로,
// status='수정중' 인 행 중 status_at 이 가장 최근인 건을 대상으로 삼는다.

const instruction = $('라우팅 판별').first().json.instruction;

const candidates = $input.all()
  .map(r => r.json)
  .filter(j => String(j.status || '').trim() === '수정중');

if (candidates.length === 0) {
  throw new Error('수정 대기 중인 문의가 없습니다. 먼저 카드에서 [✏️ 수정 요청] 을 눌러주세요.');
}

candidates.sort((a, b) => String(b.status_at || '').localeCompare(String(a.status_at || '')));
const target = candidates[0];

if (!target.final_body) {
  throw new Error(`기존 초안 본문(final_body)이 비어 있습니다: ${target.inquiry_id}`);
}

return [{
  json: {
    ...target,
    instruction: instruction
  }
}];

// P3 프롬프트를 조립한다. 컨텍스트 4개를 모두 넣는 것이 핵심이다.
// 수정 지시만 던지면 맥락이 끊겨 전혀 다른 답변이 나온다.

const ctx = $('수정 대상 찾기').first().json;

// 시트에는 조항 ID만 저장돼 있으므로 원문을 복원한다
const citedIds = String(ctx.cited_clauses || '')
  .split(',')
  .map(s => s.trim())
  .filter(Boolean);

const clauseMap = {};
const allClauses = [];
for (const item of $input.all()) {
  const j = item.json;
  if (!j.clause_id) continue;
  const id = String(j.clause_id).trim();
  clauseMap[id] = j;
  allClauses.push(`[${id}] ${j.title} — ${j.text}`);
}

const retrieved = citedIds
  .map(id => clauseMap[id])
  .filter(Boolean)
  .map(c => `[${c.clause_id}] ${c.title} — ${c.text}`)
  .join('\n') || '(인용된 조항 없음)';

const promptP3 = [
  '너는 이커머스 쇼핑몰 "온마켓"의 고객 응대 담당자다.',
  '아래 답변 초안에 대해 검토자가 수정을 요청했다. 요청받은 부분만 고쳐서 다시 작성하라.',
  '',
  '■ 절대 규칙',
  '1. 수정 요청과 무관한 문장은 원래 표현을 그대로 유지하라. 전체를 새로 쓰지 마라.',
  '2. 지시가 모호하면 가장 보수적으로 해석하라. 임의로 내용을 추가하지 마라.',
  '3. 본문에 여전히 정책 조항에 근거한 내용이 남아 있다면 그 조항 ID는 cited_clauses 에 유지하라.',
  '   검토자가 새로 넣은 내용 때문에 전체 근거를 비우지 마라.',
  '4. 이번 지시로 추가되거나 바뀐 내용을 handler_added 에 짧게 나열하라.',
  '   예) ["고객센터 번호 안내", "5% 할인 쿠폰 지급"]',
  '5. 재작성을 마친 뒤, 완성된 본문 전체를 [전체 정책 조항]과 대조하라.',
  '   본문의 서술이 어느 조항과 어긋나면 policy_conflict.detected 를 true 로 두고,',
  '   instruction 에 문제가 되는 본문 문장을 그대로,',
  '   policy 에 충돌하는 조항을 [ID] 제목 — 원문 형태로 적어라.',
  '   이번 지시로 생긴 것이든 이전 수정에서 남은 것이든 상관없이 검사한다.',
  '   어긋나지 않으면 detected 를 false, 나머지 두 필드는 빈 문자열로 둔다.',
  '   판단은 사람이 하므로 본문은 검토자 지시를 따라 작성한다. 지시를 무시하지 마라.',
  '',
  '■ 원래 고객 문의',
  ctx['문의내용'] || ctx.content || '',
  '',
  '■ 기존 초안',
  ctx.final_body,
  '',
  '■ 정책 근거 (본문 작성의 근거로 삼을 조항)',
  retrieved,
  '',
  '■ 검토자의 수정 요청',
  ctx.instruction,
  '',
  '■ 전체 정책 조항 (충돌 확인 전용)',
  '아래 목록은 policy_conflict 판정에만 사용한다.',
  '본문 작성에는 위 [정책 근거]와 검토자 지시만 쓴다. 아래 조항을 본문에 새로 끌어오지 마라.',
  allClauses.join('\n'),
  '',
  'change_note 에는 무엇을 어떻게 고쳤는지 한 문장으로 적어라.'
].join('\n');

return [{
  json: {
    ...ctx,
    retrieved_clauses: retrieved,
    prompt_p3: promptP3
  }
}];

// P3 응답 파싱 + 재검토 카드 조립

const ctx = $('P3 프롬프트 조립').first().json;

let raw = '';
try {
  raw = $input.first().json.candidates[0].content.parts[0].text;
} catch (e) {
  raw = '';
}
raw = String(raw).replace(/^\s*```(?:json)?\s*/i, '').replace(/\s*```\s*$/i, '').trim();

let p = {};
try {
  p = JSON.parse(raw);
} catch (e) {
  throw new Error('P3 재작성 응답을 파싱하지 못했습니다. 원문: ' + raw.slice(0, 300));
}

const body = p.body || '';
if (!body.trim()) throw new Error('재작성된 본문이 비어 있습니다.');

const cited   = Array.isArray(p.cited_clauses) ? p.cited_clauses : [];
const added   = Array.isArray(p.handler_added) ? p.handler_added : [];
const conf    = p.policy_conflict || {};
const hasConf = conf.detected === true;

const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const clip = (s, n) => {
  s = String(s || '').trim();
  if (n === null) return s;                 // 제한 없음
  return n <= 0 ? '' : (s.length > n ? s.slice(0, n) + ' …(생략)' : s);
};

// 감정은 불만/일반 두 값뿐이다. 조회 필요 여부는 별도 축이라 배지를 따로 붙인다.
// (이전의 3단계 객체 조회는 두 축 분리 이후 죽은 코드였다)
const badge = ctx.sentiment === '불만' ? '🔴' : '⚪';
const needsLookup = ctx.needs_lookup === true || String(ctx.needs_lookup).toUpperCase() === 'TRUE';
const nextCount = Number(ctx.revision_count || 0) + 1;

// 수정 회차가 쌓일수록 담당자가 원래 문의를 잊는다. 카드마다 원문을 다시 보여준다.
const original = ctx['문의내용'] || ctx.content || '';

function build(quoteLimit, bodyLimit) {
  const lines = [];
  lines.push(`${badge} <b>[${esc(ctx.category)}]</b> ${esc(ctx.customer_name || ctx['이름'] || '')} — 수정 ${nextCount}회차`);

  if (needsLookup) {
    lines.push('📋 <b>주문 조회 필요</b> — 고객 주문 정보를 확인해야 답이 완결됩니다');
  }

  if (hasConf) {
    lines.push('⚠️ <b>지시와 정책이 충돌합니다</b>');
    lines.push(`   문제: ${esc(conf.instruction || '')}`);
    lines.push(`   정책: ${esc(conf.policy || '')}`);
  }

  const quote = clip(original, quoteLimit);
  if (quote) {
    // <blockquote> 미사용 — 텔레그램이 태그를 거부하면 전송이 실패한다. 서식보다 전송이 중요하다.
    lines.push('──────────────');
    lines.push('💬 <b>고객 문의</b>');
    lines.push(`「${esc(quote)}」`);
  }

  lines.push('──────────────');
  lines.push(`🔁 <b>바뀐 점</b>: ${esc(p.change_note || '(설명 없음)')}`);

  if (added.length) {
    lines.push(`✍️ 담당자 추가: ${esc(added.join(', '))}`);
  }

  lines.push(`📎 근거: ${cited.length ? esc(cited.join(', ')) : '없음'}`);
  lines.push('');
  lines.push(esc(clip(body, bodyLimit)));
  lines.push('');
  lines.push(`<code>${esc(ctx.inquiry_id)}</code>`);
  return lines.join('\n');
}

// 텔레그램 메시지 한도는 4096자. **넘으면 전송이 실패하고 재검토 카드가 오지 않는다.**
// 충돌 경고와 초안 본문이 우선이므로 문의 원문부터 줄인다.
let card = build(500, null);
if (card.length > 3900) card = build(200, null);
if (card.length > 3900) card = build(0, null);
if (card.length > 3900) card = build(0, 3000);       // 마지막 방어선

return [{
  json: {
    ...ctx,
    subject: p.subject || `[온마켓] 문의하신 내용에 대한 답변입니다`,
    body: body,
    new_cited: cited.join(','),
    change_note: p.change_note || '',
    handler_added: added.join(', '),
    policy_conflict: hasConf ? `지시:${conf.instruction} / 정책:${conf.policy}` : '',
    revision_next: nextCount,
    card_text: card
  }
}];

// 수정 요청 가드 — 이미 발송된 건이 수정중으로 되돌아가는 것을 막는다.
//
// 텔레그램 카드는 발송 후에도 채팅에 남고 버튼이 계속 눌린다.
// 승인 경로에는 중복 방어가 있었지만(대상 조회(승인)) 수정 경로에는 없어서,
// 발송이 끝난 건을 다시 수정 루프에 넣을 수 있었다.
// 그 상태에서 승인을 누르면 같은 고객에게 두 번째 메일이 나간다.

const target = $('라우팅 판별').first().json.inquiry_id;

const hit = $input.all().find(
  r => String(r.json.inquiry_id || '').trim() === target
);

if (!hit) {
  throw new Error(`문의를 찾을 수 없습니다: ${target}`);
}

const status = String(hit.json.status || '').trim();
const sentAt = String(hit.json.sent_at || '').trim();

// status 와 sent_at 을 둘 다 본다. 상태가 어떤 경로로든 바뀌어 있어도
// 발송 기록이 남아 있으면 이미 나간 건이다.
const alreadySent = status === '발송완료' || sentAt !== '';

// 안내 문구는 여기서 만든다. 텔레그램 노드의 표현식 안에서 줄바꿈을
// 다루면 이스케이프가 깨지기 쉽다. 카드 문구를 Code 에서 조립하는
// 초안 파싱·재작성 파싱과 같은 방식이다.
const esc = s => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const blockText = [
  '🚫 <b>이미 발송된 건입니다</b>',
  `[${esc(hit.json.inquiry_id)}] ${esc(hit.json['이름'])} · ${esc(hit.json.category)}`,
  `발송 시각: ${esc(sentAt)}`,
  '',
  '이 카드는 지난 기록입니다. 수정이 필요하면 새로 접수해 주세요.'
].join('\n');

return [{
  json: {
    ...hit.json,
    already_sent: alreadySent,
    current_status: status,
    block_text: blockText
  }
}];
